import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem119 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["OADfHMMVftq1AKtGgcaP","Smart Tv Roku Tv 50 7045 4k Uhd Aoc Bivolt","Smart TV AOC Roku de 50″ — 4K UHD anunciado","https://www.mercadolivre.com.br/p/MLB51202548"],["Oelq1fEuR41tSXxHj8cp","Extensão Elétrica Tomadas Usb Type-c Bivolt 2m Chave Liga","Extensão elétrica com seis tomadas, USB-A e USB-C anunciados","https://www.mercadolivre.com.br/up/MLBU4319551132?pdp_filters=item_id%3AMLB4890245591"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
